{"code": "import impl
import pytest


def test_allow_simple():
    """A matching ALLOW policy grants access."""
    request = {'subject': 'alice', 'roles': [], 'action': 'read', 'resource': 'file.txt'}
    policies = [{'effect': 'ALLOW', 'principal': 'user:alice', 'action': 'read', 'resource': 'file.txt'}]
    assert impl.authorize(request, policies) == 'ALLOW'


def test_deny_simple():
    """A matching DENY policy denies access."""
    request = {'subject': 'alice', 'roles': [], 'action': 'read', 'resource': 'file.txt'}
    policies = [{'effect': 'DENY', 'principal': 'user:alice', 'action': 'read', 'resource': 'file.txt'}]
    assert impl.authorize(request, policies) == 'DENY'


def test_default_deny():
    """No policies or no matching policies means default deny."""
    request = {'subject': 'alice', 'roles': [], 'action': 'read', 'resource': 'file.txt'}
    assert impl.authorize(request, []) == 'DENY'

    policies = [{'effect': 'ALLOW', 'principal': 'user:bob', 'action': 'read', 'resource': 'file.txt'}]
    assert impl.authorize(request, policies) == 'DENY'


def test_deny_overrides_allow():
    """DENY overrides ALLOW regardless of order or specificity."""
    request = {'subject': 'alice', 'roles': ['contractor'], 'action': 'read', 'resource': 'docs/reports/Q1'}
    policies = [
        {'effect': 'ALLOW', 'principal': 'user:alice', 'action': '*', 'resource': '*'},
        {'effect': 'DENY', 'principal': 'role:contractor', 'action': 'read', 'resource': 'docs/reports/*'},
    ]
    assert impl.authorize(request, policies) == 'DENY'


def test_principal_wildcard():
    """* principal matches any request."""
    request = {'subject': 'anyone', 'roles': [], 'action': 'read', 'resource': 'file.txt'}
    policies = [{'effect': 'ALLOW', 'principal': '*', 'action': 'read', 'resource': 'file.txt'}]
    assert impl.authorize(request, policies) == 'ALLOW'


def test_principal_user():
    """user: principal matches exact subject."""
    request = {'subject': 'alice', 'roles': [], 'action': 'read', 'resource': 'file.txt'}
    policies = [{'effect': 'ALLOW', 'principal': 'user:alice', 'action': 'read', 'resource': 'file.txt'}]
    assert impl.authorize(request, policies) == 'ALLOW'

    request2 = {'subject': 'bob', 'roles': [], 'action': 'read', 'resource': 'file.txt'}
    assert impl.authorize(request2, policies) == 'DENY'


def test_principal_role():
