    request = {'subject': 'alice', 'roles': ['admin', 'user'], 'action': 'read', 'resource': 'file.txt'}
    policies = [{'effect': 'ALLOW', 'principal': 'role:admin', 'action': 'read', 'resource': 'file.txt'}]
    assert impl.authorize(request, policies) == 'ALLOW'

