def test_validate_request_required_fields():
    """Request must have subject, roles, action, resource."""
    base = {'subject': 'alice', 'roles': [], 'action': 'read', 'resource': 'file.txt'}

    for field in ['subject', 'roles', 'action', 'resource']:
        req = {k: v for k, v in base.items() if k != field}
        with pytest.raises(ValueError, match=f"missing '{field}'"):
            impl.authorize(req, [])


def test_validate_request_roles_type():
    """Request roles must be a list."""
    request = {'subject': 'alice', 'roles': 'admin', 'action': 'read', 'resource': 'file.txt'}
    with pytest.raises(ValueError, match="'roles' must be a list"):
        impl.authorize(request, [])


def test_validate_policy_required_fields():
    """Policy must have effect, principal, action, resource."""
    request = {'subject': 'alice', 'roles': [], 'action': 'read', 'resource': 'file.txt'}
    base = {'effect': 'ALLOW', 'principal': '*', 'action': 'read', 'resource': 'file.txt'}

    for field in ['effect', 'principal', 'action', 'resource']:
        policy = {k: v for k, v in base.items() if k != field}
        with pytest.raises(ValueError, match=f"missing '{field}'"):
            impl.authorize(request, [policy])


def test_validate_policy_effect():
    """Policy effect must be exactly 'ALLOW' or 'DENY'."""
    request = {'subject': 'alice', 'roles': [], 'action': 'read', 'resource': 'file.txt'}

    for bad_effect in ['Allow', 'PERMIT', 'Deny', 'allow', 'deny']:
        policy = {'effect': bad_effect, 'principal': '*', 'action': 'read', 'resource': 'file.txt'}
        with pytest.raises(ValueError, match="'ALLOW' or 'DENY'"):
            impl.authorize(request, [policy])


def test_extra_fields_ignored():
    """Extra fields in request and policies are ignored."""
